item.content:encoded:
/* Dimitrium sticky header */
header.wp-block-template-part {
  position: sticky;
  top: 0;
  z-index: 1000;
}

.main-header {
  position: relative;
}

@media (max-width: 600px) {
  .main-header {
    padding-top: 16px !important;
    padding-bottom: 16px !important;
  }
}

/* Dimitrium mobile hero spacing */
@media (max-width: 600px) {
  div.main-hero {
    padding-top: 16px !important;
    padding-bottom: 16px !important;
  }

  div.main-hero &gt; * + * {
    margin-block-start: 16px !important;
  }
}

/* Dimitrium language switcher */
.dimitrium-language-switcher {
  display: flex;
  align-items: center;
  gap: 8px;
  margin: 0;
  padding: 0;
  list-style: none;
}
.dimitrium-language-switcher li {
  margin: 0;
  padding: 0;
}
.dimitrium-language-switcher a {
  color: #fff;
  text-decoration: none;
  font-size: 0.8rem;
  font-weight: 600;
  text-transform: uppercase;
}
.dimitrium-language-switcher a {
  opacity: 0.55;
}
.dimitrium-language-switcher .current-lang a {
  opacity: 1;
}

/* Dimitrium translated home page wrapper reset */
body.page-id-122 .wp-block-post-content,
body.page-id-123 .wp-block-post-content {
  width: 100%;
  max-width: none !important;
  margin: 0 !important;
  padding: 0 !important;
}

/* Dimitrium floating language switcher */
ul.dimitrium-language-switcher {
  position: fixed;
  right: max(16px, env(safe-area-inset-right));
  bottom: max(16px, env(safe-area-inset-bottom));
  z-index: 1000002;
  gap: 10px;
  margin: 0 !important;
  padding: 12px 20px !important;
  background: #141516;
  border: 1px solid rgba(247, 248, 248, 0.12);
  border-radius: 999px;
  box-shadow: 0 8px 24px rgba(0, 0, 0, 0.28);
}

/* Dimitrium translated home mobile horizontal padding */
@media (max-width: 600px) {
  body.page-id-122 main div.main-hero,
  body.page-id-123 main div.main-hero {
    padding-left: 16px !important;
    padding-right: 16px !important;
  }
}

/* Dimitrium bilingual footer */
.footer-copy-sr,
.footer-tagline-sr {
  display: none;
}
html[lang^="sr"] .footer-copy-en,
html[lang^="sr"] .footer-tagline-en {
  display: none;
}
html[lang^="sr"] .footer-copy-sr,
html[lang^="sr"] .footer-tagline-sr {
  display: block;
}

/* Dimitrium language switcher separator */
.dimitrium-language-switcher li + li {
  display: flex;
  align-items: center;
  gap: 8px;
}
.dimitrium-language-switcher li + li::before {
  content: "/";
  color: #fff;
  opacity: 0.45;
}

/* Dimitrium language switcher vertical alignment */
.dimitrium-language-switcher li {
  display: flex;
  align-items: center;
}
.dimitrium-language-switcher a,
.dimitrium-language-switcher li::before {
  display: block;
  line-height: 1;
}

/* Dimitrium mobile roadmap heading */
@media (max-width: 600px) {
  body.page-id-122 main .roadmap-heading,
  body.page-id-123 main .roadmap-heading {
    margin-top: 24px !important;
    margin-block-start: 24px !important;
    font-size: 1.5rem !important;
  }
}

/* Dimitrium desktop page-links spacing */
@media (min-width: 601px) {
  .dimitrium-page-links {
    margin-block-start: 40px !important;
  }
}

/* Dimitrium mobile cat page spacing */
@media (max-width: 600px) {
  body.page-id-146 .wp-block-post-content &gt; * + *,
  body.page-id-147 .wp-block-post-content &gt; * + * {
    margin-block-start: 16px !important;
  }
}

/* Noir responsive row */
body.page-id-175 .noir-row,
body.page-id-179 .noir-row {
  flex-direction: row !important;
}

@media (max-width: 600px) {
  body.page-id-175 .noir-row,
  body.page-id-179 .noir-row {
    flex-direction: column !important;
  }
}

/* Noir mobile logo size */
@media (max-width: 600px) {
  body.page-id-175 .noir-row &gt; .wp-block-image,
  body.page-id-179 .noir-row &gt; .wp-block-image {
    width: 256px !important;
    flex-basis: auto !important;
    align-self: flex-start;
    margin-inline: 0;
    padding-inline: 0;
  }
}

/* Noir mobile headings */
@media (max-width: 600px) {
  body.page-id-175 .noir-row .wp-block-heading,
  body.page-id-179 .noir-row .wp-block-heading {
    font-size: 2rem !important;
  }

  body.page-id-175 .noir-row + .wp-block-heading,
  body.page-id-179 .noir-row + .wp-block-heading {
    margin-bottom: 16px !important;
  }

  body.page-id-175 .noir-row + .wp-block-heading + .wp-block-group,
  body.page-id-179 .noir-row + .wp-block-heading + .wp-block-group {
    margin-block-start: 16px !important;
  }
}

/* Dimitrium Flex mobile content gap */
@media (max-width: 600px) {
  body.page-id-223 .wp-block-post-content &gt; * + *,
  body.page-id-224 .wp-block-post-content &gt; * + * {
    margin-block-start: 16px !important;
  }
}

/* Dimitrium Flex desktop grid gap */
@media (min-width: 601px) {
  body.page-id-223 .wp-block-heading + .dimitrium-flex-grid,
  body.page-id-224 .wp-block-heading + .dimitrium-flex-grid,
  body.page-id-223 .wp-block-heading + .dimitrium-project-grid,
  body.page-id-224 .wp-block-heading + .dimitrium-project-grid {
    margin-block-start: 40px !important;
  }
}

/* Dimitrium Flex project grid mobile containment */
@media (max-width: 700px) {
  body.page-id-223 .dimitrium-project-grid,
  body.page-id-224 .dimitrium-project-grid,
  body.page-id-223 .dimitrium-project-card,
  body.page-id-224 .dimitrium-project-card {
    box-sizing: border-box;
    width: 100%;
    max-width: 100%;
    min-width: 0;
  }
}


/* Dimipedia hero: preserve the full-bleed image while softening it behind the logo. */
body.page-id-463 .dimipedia-hero .wp-block-cover__image-background,
body.page-id-465 .dimipedia-hero .wp-block-cover__image-background {
  filter: blur(6px) !important;
  transform: scale(1.035) !important;
}
